{
  "description": "Rendiconti e relazioni",
  "baseAnalyzerId": "prebuilt-document",
  "config": {
    "enableFigureAnalysis": true,
    "chartFormat": "chartjs",
    "enableSegment": true
  },
  "fieldSchema": {
    "fields": {
      "Righe": {
        "type": "array",
        "description": "Una voce per riga della tabella principale, escluse le righe marcate come superate; la tabella può continuare su più pagine.",
        "items": {
          "type": "object",
          "properties": {
            "Prodotto": {
              "type": "string"
            },
            "Quantita": {
              "type": "number"
            },
            "Importo": {
              "type": "number"
            }
          }
        }
      },
      "Totale": {
        "type": "number",
        "method": "extract",
        "estimateSourceAndConfidence": true,
        "description": "Importo dopo \"Totale complessivo\" in fondo all'ultima pagina; esclude i subtotali di pagina."
      },
      "Fornitore": {
        "type": "string",
        "method": "extract",
        "estimateSourceAndConfidence": true,
        "description": "Ragione sociale del fornitore in intestazione."
      },
      "Unita": {
        "type": "string",
        "method": "classify",
        "enum": [
          "euro",
          "migliaia di euro",
          "milioni di euro",
          "altro"
        ],
        "description": "Unità dei valori indicata nella nota a piè di pagina."
      }
    }
  }
}
